<script setup lang="ts">
import MeetingInfoEditor from '../meetings/MeetingInfoEditor.vue';
import {canPrepareFinalInformation} from './final-information';
import {computed,shallowRef,ref,watch,onUnmounted} from 'vue';import {useApplication} from '../../application';import {usePublication} from './usePublication';import type {SavedMeeting} from '../../shared/api/meeting-info';import type {MinutesCurrent} from '../../shared/api/minutes-saved';import type {Libraries,Folders} from '../../shared/api/publications';import type {components} from '../../shared/api/generated';import {ApiError} from '../../shared/api/client';
const localControlled=import.meta.env.DEV&&import.meta.env.VITE_LOCAL_DEV_LOGIN==='1';
const props=defineProps<{meetingId:string;owner:boolean;locked:boolean;targetLabels?:Record<string,string>;meetingInfo?:SavedMeeting;savedMinutes?:MinutesCurrent;stage?:string}>();const emit=defineEmits<{changed:[];denied:[cause:unknown];editInfo:[];published:[];infoSaved:[];navigate:[stage:string]}>();const app=useApplication();
const p=usePublication({...app.publications,authorize:async(id,s)=>{const n=await app.workspace.navigation(id,s);return n.relation!=='OWNER'?false:n.navigationState==='PUBLISHED_READ_ONLY'?'READ_ONLY':n.navigationState==='CHECK_PRODUCER';}},()=>app.session.current.value?.actor.enterpriseId??null,()=>props.meetingId,()=>props.owner,()=>app.minutesScopeReady.value,()=>props.locked,app.journals,cause=>{clear();emit('denied',cause);});
const canPrepareFinal=computed(()=>canPrepareFinalInformation(p.readiness.value));
const embeddedInfo=ref<InstanceType<typeof MeetingInfoEditor>>(),successDialog=ref<HTMLDialogElement>(),submitted=ref(false),successShown=ref(false);let pollEpoch=0,pollTimer:ReturnType<typeof setTimeout>|null=null;
const libraries=shallowRef<Libraries|null>(null),folders=shallowRef<Folders|null>(null),library=ref(''),parent=ref<string|null>(null),folder=ref(''),destinationProvider=ref(''),error=ref(''),reading=ref(false),optional=ref<string[]>([]),requirementPage=ref(0),frozenPage=ref(0),attempts=shallowRef<components['schemas']['AttemptPage']|null>(null);let epoch=0,controller:AbortController|null=null;
const remoteLabels:Record<string,string>={SUCCESS:'知识库已保存',FAILED:'知识库已拒绝',UNKNOWN:'结果待查回',NOT_OBSERVED:'尚未确认'};
const applicationLabels:Record<string,string>={APPLIED:'已应用',PENDING:'等待应用',DISCARDED:'未应用',FAILED:'应用失败',NOT_APPLIED:'尚未应用'};
const stateLabels:Record<string,string>={READY:'等待发布',RUNNING:'正在发布',RECONCILING:'正在查回结果',FAILED:'发布失败',SUCCEEDED:'已发布'};
const blockerLabels:Record<string,string>={BODY_REQUIRED:'请先生成或保存纪要正文',ELEMENT_SET_REQUIRED:'请先生成并采用核心要素',GENERATION_REQUIRED:'内容或设置已变更，请重新生成',SETTINGS_REQUIRED:'请先选择模板与初始设置',REVIEW_REQUIRED:'请完成下方标为待完成的必需审阅',PENDING_CANDIDATE:'请先处置待决定候选',OUTSTANDING_GENERATION:'请等待当前处理任务结束',TRANSCRIPT_CONFIRMATION_REQUIRED:'请先确认已保存转写',CORRECTION_UNAVAILABLE:'转写校正服务尚不可用',MATERIALS_UNAVAILABLE:'背景材料暂不可读取，请核对会议文件',PUBLISHED:'会议已发布，请查看已发布纪要',PUBLICATION_BUSY:'发布任务尚未结束，请查回当前结果',MEETING_INFO_REQUIRED:'请补全并保存会议信息',ROSTER_CONFIRMATION_REQUIRED:'请确认已保存的参会名单',SAVED_SOURCE_OR_SETTINGS_STALE:'来源或设置已变化，请重新生成并采用纪要',SENSITIVITY_UNRESOLVED:'请核对敏感信息并保存排除选择后重新生成',EXCLUDED_SOURCE_USED:'当前纪要包含已排除来源，请重新生成并采用',TASK11_NOT_INSTALLED:'最终确认服务尚未启用'};
const selectedDestination=shallowRef<{providerId:string;libraryId:string;folderId:string;libraryName:string;folderName:string}|null>(null);
function selectLibrary(lib:Libraries['items'][number]){if(!libraries.value)return;selectedDestination.value={providerId:libraries.value.providerId,libraryId:lib.id,folderId:lib.rootFolderId,libraryName:lib.name,folderName:'根目录'};folder.value=lib.rootFolderId;loadFolders(lib.id);}
function selectFolder(f:Folders['items'][number]){if(!folders.value)return;selectedDestination.value={providerId:folders.value.providerId,libraryId:f.libraryId,folderId:f.id,libraryName:libraryName.value||selectedDestination.value?.libraryName||f.libraryId,folderName:f.name};}
const status=computed(()=>p.current.value?.publication),message=computed(()=>p.error.value instanceof Error?p.error.value.message:'发布状态暂不可用。');
watch(()=>p.final.value?.confirmation?.id,()=>emit('changed'));
watch(()=>status.value,value=>{if(value?.rawState==='SUCCEEDED'&&value.remoteOutcome==='SUCCESS'&&value.applicationOutcome==='APPLIED'){emit('published');if(!successShown.value&&(submitted.value||p.command.snapshot.value?.operation==='PUBLICATION_SUBMIT')){successShown.value=true;successDialog.value?.showModal();}}});
async function read<T>(fn:(s:AbortSignal)=>Promise<T>,accept:(v:T)=>void){const turn=++epoch;controller?.abort();const request=new AbortController();controller=request;reading.value=true;error.value='';try{const v=await fn(request.signal);if(turn===epoch)accept(v);}catch(cause){if(turn===epoch){if(cause instanceof ApiError&&[401,403].includes(cause.status)){p.deny(cause);}error.value=cause instanceof Error?cause.message:'目录暂不可用。';}}finally{if(turn===epoch)reading.value=false;}}
function clear(){epoch++;controller?.abort();libraries.value=null;folders.value=null;library.value='';parent.value=null;folder.value='';destinationProvider.value='';selectedDestination.value=null;optional.value=[];attempts.value=null;error.value='';reading.value=false;}
function loadLibraries(cursor:string|null=null){folders.value=null;library.value='';void read(s=>app.publications.libraries(props.meetingId,cursor,s),v=>libraries.value=v);}
function loadFolders(selectedLibrary:string,selectedParent:string|null=null,cursor:string|null=null){library.value=selectedLibrary;parent.value=selectedParent;void read(s=>app.publications.folders(props.meetingId,selectedLibrary,selectedParent,cursor,s),v=>{folders.value=v;destinationProvider.value=v.providerId;});}
async function run(fn:()=>Promise<void>){try{await fn();if(!p.error.value)emit('changed');}catch(cause){error.value=cause instanceof Error?cause.message:'操作暂不可用。';}}
function publish(){const selected=selectedDestination.value;if(!selected){error.value='请先选择真实知识库或文件夹。';return;}submitted.value=true;void run(()=>p.submit({providerId:selected.providerId,libraryId:selected.libraryId,folderId:selected.folderId}));}
function loadAttempts(cursor:string|null=null){const id=status.value?.publicationId;if(id)void read(s=>app.publications.attempts(props.meetingId,id,cursor,s),v=>attempts.value=v);}
const stop=watch(()=>[app.session.current.value?.actor.enterpriseId,props.meetingId,props.owner,app.minutesScopeReady.value],()=>{clear();if(app.session.current.value)void p.reload();},{immediate:true,flush:'sync'});onUnmounted(()=>{pollEpoch++;if(pollTimer)clearTimeout(pollTimer);stop();clear();p.dispose();});

watch(()=>status.value?.publicationId,id=>{if(!id)return;const turn=++pollEpoch;let attempts=0;async function tick(){if(turn!==pollEpoch||!status.value||status.value.publicationId!==id)return;if(['READY','RUNNING','RECONCILING'].includes(status.value.rawState)&&attempts++<30){await p.reload();if(turn===pollEpoch)pollTimer=setTimeout(tick,2000);}}pollTimer=setTimeout(tick,1500);});
watch(()=>props.stage,()=>{if(app.session.current.value)void p.reload();});
const librarySearch=ref(''),folderSearch=ref('');
const visibleLibraries=computed(()=>libraries.value?.items.filter(x=>x.name.toLocaleLowerCase().includes(librarySearch.value.toLocaleLowerCase()))??[]);
const visibleFolders=computed(()=>folders.value?.items.filter(x=>x.name.toLocaleLowerCase().includes(folderSearch.value.toLocaleLowerCase()))??[]);
const libraryName=computed(()=>libraries.value?.items.find(x=>x.id===library.value)?.name??'');
async function confirmFinal(){if(embeddedInfo.value){const ready=await embeddedInfo.value.prepareFinal();if(!ready)return;emit('infoSaved');await p.reload();}await run(()=>p.confirm(optional.value));if(p.final.value?.confirmation&&!p.error.value)emit('navigate','publish');}
watch(()=>[props.stage,p.final.value?.confirmation?.id,status.value?.publicationId],()=>{if(props.stage==='publish'&&p.final.value?.confirmation&&!status.value&&!libraries.value&&!reading.value)loadLibraries();});
</script>
<template><section class="publication" :class="{'m19-published-summary':stage==='published'}"><p v-if="p.error.value" role="alert">{{message}}</p><p v-if="error" role="alert">{{error}}</p>
 <template v-if="stage==='confirm'"><div class="ac-confirm-grid"><section class="card ac-confirm-info"><div class="card-h between"><h3>会议信息</h3><button v-if="owner&&!p.final.value?.confirmation" class="btn sm ghost" :disabled="locked||p.busy.value" @click="emit('editInfo')">编辑会议信息</button></div><div class="card-p"><MeetingInfoEditor v-if="owner&&!p.final.value?.confirmation" ref="embeddedInfo" presentation="final" :meeting-id="meetingId" :eligible="true" @saved="emit('infoSaved');p.reload()"/><template v-else><label class="form-label">会议名称 <span class="required">*</span></label><input class="input" readonly :value="meetingInfo?.name??''"/><label class="form-label mt16">会议日期 <span class="required">*</span></label><input class="input" type="date" readonly :value="meetingInfo?.occurredOn??''"/><label class="form-label mt16">会议分类 <span class="required">*</span></label><input class="input" readonly :value="meetingInfo?.category??''"/><label class="form-label mt16">会议摘要</label><div class="confirm-description">{{meetingInfo?.summary||'暂无会议摘要'}}</div><label class="form-label mt16">参会人 <span class="required">*</span></label><div class="confirm-participants"><span v-for="person in meetingInfo?.confirmedRoster??[]" :key="person.memberId" class="tag orange">{{person.displayName}}</span><span v-if="!meetingInfo?.confirmedRosterId" class="muted">尚未确认参会人员</span></div><p class="small muted mt12">最终确认使用已保存信息与已确认名单。</p></template><p v-if="owner&&!p.final.value?.confirmation" class="small muted mt12">最终确认将保存当前会议信息、确认参会名单并更新访问权限。</p></div></section><section class="card ac-confirm-preview"><div class="card-h"><h3>会议纪要</h3></div><div class="card-p"><h2>{{savedMinutes?.body?.title}}</h2><pre>{{savedMinutes?.body?.body}}</pre><div v-if="!savedMinutes?.body" class="empty">尚无已保存纪要</div></div></section></div>
 <details v-if="owner&&p.readiness.value" class="readiness-details" :open="!p.readiness.value.ready"><summary>{{p.readiness.value.ready?'全部最终确认条件已满足':'请完成最终确认条件'}}</summary><ul><li v-for="b in p.readiness.value.blockers" :key="b" :title="b">{{blockerLabels[b]??b}}</li></ul><p>待处置候选 {{p.readiness.value.pendingCandidateIds.length}} 项 · 未完成任务 {{p.readiness.value.outstandingTaskIds.length}} 项</p><ul><li v-for="r in p.readiness.value.required.slice(requirementPage*20,(requirementPage+1)*20)" :key="r.targetId+r.reviewKind">{{r.reviewKind==='ACTION_FIELDS'?'行动字段':'全文来源'}} · {{targetLabels?.[r.targetId]??'当前条目'}} · {{r.satisfied?'已满足':'待完成'}}</li></ul><div class="flex"><button v-if="requirementPage>0" class="btn sm" @click="requirementPage--">上一页条件</button><button v-if="(requirementPage+1)*20<p.readiness.value.required.length" class="btn sm" @click="requirementPage++">下一页条件</button><button class="btn sm" @click="emit('navigate','minutes')">返回纪要完成审阅</button></div><details v-if="p.readiness.value.optionalReviewIds.length"><summary>选择一并冻结的可选审阅</summary><label v-for="id in p.readiness.value.optionalReviewIds" :key="id"><input v-model="optional" type="checkbox" :value="id"/>{{id}}</label></details></details>
 <footer v-if="owner&&!p.final.value?.confirmation" class="acf-dock"><div class="acf-inner"><span class="acf-hint">{{p.final.value?.confirmation?'当前版本已最终确认。':'最终确认将保存会议信息、确认参会名单并更新访问权限；会议名称、会议日期和分类必填。'}}</span><button class="btn" @click="emit('navigate','minutes')">返回纪要编辑</button><button v-if="p.final.value?.confirmation" class="btn primary" @click="emit('navigate','publish')">继续发布 ›</button><button v-else class="btn primary" :disabled="locked||p.busy.value||(!canPrepareFinal||!embeddedInfo?.canPrepare)" @click="confirmFinal">最终确认并继续发布</button></div></footer></template>
 <template v-if="stage==='publish'"><div class="ac-publish-grid"><section class="card pub-location-card"><div class="card-h"><h3>选择知识库位置</h3><p class="small muted mt8">会议纪要将发布到选定的知识库文件夹。</p></div><div class="card-p"><div class="pub-location-columns"><section><label class="form-label">知识库</label><input v-model="librarySearch" class="input" placeholder="搜索当前页知识库"/><p v-if="reading" class="small muted mt12">正在读取目录…</p><div class="pub-location-list"><button v-for="lib in visibleLibraries" :key="lib.id" class="pub-location-item" :class="{selected:library===lib.id}" :disabled="!!status||locked" @click="selectLibrary(lib)"><span>▱ {{lib.name}}</span><span>›</span></button><p v-if="libraries&&!visibleLibraries.length" class="small muted">没有匹配的知识库</p></div><button v-if="libraries?.hasMore" class="btn sm" @click="loadLibraries(libraries.nextCursor)">更多知识库</button><button v-if="!libraries&&!reading&&!status" class="btn sm" @click="loadLibraries()">读取知识库</button></section><section><label class="form-label">文件夹 <span class="small muted">{{libraryName}}</span></label><input v-model="folderSearch" class="input" placeholder="搜索当前页文件夹"/><div class="pub-folder-breadcrumb"><button class="btn sm ghost" :disabled="!library||reading" @click="loadFolders(library)">根目录</button><span v-if="parent"> / 子目录</span></div><div class="pub-location-list"><div v-for="f in visibleFolders" :key="f.id" class="pub-location-folder" :class="{selected:folder===f.id}"><label><input v-model="folder" type="radio" :value="f.id" :disabled="locked||!!status" @change="selectFolder(f)"/>▱ {{f.name}}</label><button class="btn sm ghost" :disabled="reading||!!status" @click="loadFolders(library,f.id)">›</button></div><p v-if="!library" class="empty small">请先选择知识库</p><p v-else-if="folders&&!visibleFolders.length" class="empty small">没有匹配的文件夹</p></div><button v-if="folders?.hasMore" class="btn sm" @click="loadFolders(library,parent,folders.nextCursor)">更多文件夹</button></section></div><div class="pub-selected-location"><b>发布位置</b><p>{{selectedDestination?.libraryName??'尚未选择知识库'}} / {{selectedDestination?.folderName??'尚未选择文件夹'}}</p></div></div></section><section class="card pub-preview-card"><div class="card-h"><h3>纪要预览</h3><p class="small muted">已最终确认的版本</p></div><div class="card-p"><h2>{{p.final.value?.body?.title}}</h2><pre>{{p.final.value?.body?.body}}</pre><p v-if="!p.final.value?.confirmation" class="muted">请先完成会议最终确认。</p></div></section></div><footer v-if="owner" class="acf-dock"><div class="acf-inner"><span class="acf-hint">{{localControlled?'本地受控知识库 · 发布真实保存受控文档':'发布后会议将保持只读。'}}</span><button class="btn" @click="emit('navigate','confirm')">上一步</button><button class="btn primary" :disabled="!selectedDestination||locked||p.busy.value||!!status||!p.final.value?.confirmation" @click="publish">发布到知识库</button></div></footer></template>
 <article v-if="status" class="card publication-status"><div class="between"><h3>{{stateLabels[status.rawState]??'发布状态'}}</h3><button class="btn sm" :disabled="p.busy.value" @click="run(p.reload)">刷新最终状态</button></div><p class="small muted">{{remoteLabels[status.remoteOutcome]??status.remoteOutcome}} · {{applicationLabels[status.applicationOutcome]??status.applicationOutcome}}</p><p v-if="status.remoteOutcome==='UNKNOWN'">远端结果尚未确定。请刷新查询，当前不能再次发送。</p><p v-if="status.applicationOutcome==='FENCED_MANUAL'">该发布关联需要人工处理，当前页面只提供结果查看。</p><a v-if="status.officialDocumentUrl" class="btn primary mt12" :href="status.officialDocumentUrl" target="_blank" rel="noopener">查看正式文档 ↗</a><p v-else class="small muted">正式文档入口当前不可用。</p><details v-if="owner" class="mt12"><summary @click="loadAttempts()">发布尝试记录</summary><ul v-if="attempts"><li v-for="a in attempts.items" :key="a.attemptId">{{a.kind}} · {{a.remoteOutcome}} · {{a.applicationOutcome}} · {{a.createdAt}}</li></ul><button v-if="attempts?.hasMore" class="btn sm" @click="loadAttempts(attempts.nextCursor)">下一页尝试</button></details></article>
 <p v-if="p.command.state.value==='ACKNOWLEDGED'" class="small muted">已收到原操作回执；发布是否完成以上方当前状态为准。</p><button v-if="p.command.snapshot.value&&['PREPARED','UNCERTAIN'].includes(p.command.state.value)" class="btn" :disabled="p.busy.value" @click="run(p.retry)">{{p.command.snapshot.value.operation==='PUBLICATION_SUBMIT'?'查回原发布状态':'查回原最终确认'}}</button><button v-if="['CONFLICT','REJECTED'].includes(p.command.state.value)" class="btn" @click="p.reset();p.reload()">重新读取后再决定</button>
<dialog ref="successDialog" class="notice-dialog" aria-labelledby="publication-success-title"><h3 id="publication-success-title">发布成功</h3><p class="mt16">会议纪要已发布到知识库，会议已切换为只读。</p><p class="small muted mt12">{{selectedDestination?.libraryName}} / {{selectedDestination?.folderName}}</p><div class="flex mt16"><a v-if="status?.officialDocumentUrl" class="btn" :href="status.officialDocumentUrl" target="_blank" rel="noopener">查看正式文档</a><button class="btn primary" @click="successDialog?.close()">知道了</button></div></dialog></section></template>
<style scoped>
.publication{min-width:0}.publication [role=alert]{padding:12px;background:#fff7ed;color:#9a3412}.ac-confirm-grid{display:grid;grid-template-columns:minmax(0,.9fr) minmax(0,1.3fr);gap:16px;align-items:start}.card-h h3{font-size:15px}.ac-confirm-info .input{width:100%;margin-top:7px}.required{color:var(--red)}.confirm-description{min-height:70px;line-height:1.8;margin-top:8px;padding:10px 12px;border:1px solid var(--border);border-radius:6px;white-space:pre-wrap}.confirm-participants{display:flex;flex-wrap:wrap;gap:8px;margin-top:10px}.ac-confirm-preview h2,.pub-preview-card h2{font-size:20px;margin-bottom:14px;color:var(--navy)}.publication pre{white-space:pre-wrap;overflow-wrap:anywhere;font:inherit;line-height:1.85}.ac-confirm-preview .card-p,.pub-preview-card .card-p{max-height:calc(100dvh - 350px);overflow:auto}.readiness-details{margin:16px 0;padding:14px 18px;background:#fffaf1;border:1px solid #f6dfb1;border-radius:8px;font-size:12px}.readiness-details ul{padding-left:22px;margin:12px 0}.readiness-details p{margin:10px 0}.ac-publish-grid{display:grid;grid-template-columns:minmax(0,1.2fr) minmax(0,.8fr);gap:16px}.pub-location-columns{display:grid;grid-template-columns:1fr 1fr;gap:16px}.pub-location-columns>section{min-width:0}.pub-location-columns .input{width:100%;margin-top:8px}.pub-location-list{min-height:230px;max-height:330px;overflow:auto;margin-top:12px}.pub-location-item,.pub-location-folder{display:flex;justify-content:space-between;align-items:center;gap:10px;width:100%;padding:12px;border:0;background:white;color:var(--text);font:inherit;border-radius:6px;cursor:pointer}.pub-location-item.selected,.pub-location-folder.selected{background:var(--orange-bg);color:var(--orange)}.pub-location-item:hover,.pub-location-folder:hover{background:var(--bg)}.pub-location-folder label{display:flex;gap:8px;align-items:center}.pub-folder-breadcrumb{height:36px}.pub-selected-location{border-top:1px solid var(--border);padding-top:14px;margin-top:12px;font-size:12px}.pub-selected-location p{margin-top:8px;color:var(--muted)}.publication-status{padding:18px;margin:16px 0}.publication-status p{margin-top:8px}.acf-inner{max-width:1552px;margin:auto;display:flex;align-items:center;gap:12px}.acf-hint{flex:1;font-size:12px;color:var(--muted)}@media(max-width:1000px){.ac-confirm-grid,.ac-publish-grid{grid-template-columns:1fr}.ac-confirm-preview .card-p,.pub-preview-card .card-p{max-height:none}}@media(max-width:600px){.pub-location-columns{grid-template-columns:1fr}.acf-inner{flex-wrap:wrap}}
</style>

<style scoped>.ac-confirm-info :deep(.info-editor){padding-bottom:0}.ac-confirm-info :deep(.ac-info-drawer-footer){display:none}.ac-confirm-info :deep(.info-editor [role=status]){font-size:12px}</style>
